/* New Meridian processes (v8): Events coordination, Law enforcement, Enterprise IT, Human resources. Pure data, no imports. */
export const MORE = [
 /* ---------------- Events coordination ---------------- */
 {fn:'events', area:'ev-internal',
  proc:{id:'speakers', name:'Conference speaker logistics', d:'Invite speakers to the annual research conference, arrange their travel, collect bios and slides, and brief the moderators.', rating:2, why:'About seventy speakers a year, most of them in one autumn rush. The real problems are a missing form and a deadline tracker; only the moderator briefs are language work worth a tool.'},
  intro:'Each autumn the Bank hosts a two-day research conference, with two smaller workshops in spring: about seventy speakers and discussants a year, many flying in from abroad. Two coordinators from the internal events team handle every invitation, flight and slide deck. Walk a speaker from invitation to the podium.',
  steps:[
  {n:'Invite and confirm speakers', who:'Conference coordinators and the research director’s office', vol:'About 70 invitations a year', sys:'Email, Word templates, speaker spreadsheet',
   notes:'The programme committee picks the papers and speakers. Coordinators then write to each one on the research director’s behalf: the invitation, the session, the honorarium and the dates. Each letter is adapted from last year’s.',
   pain:'About an hour per letter, and two went out last year with the wrong session date.',
   p:'draft text low mid', alt:'shape:coordinate', best:'draft', ok:'rules retrieve', auto:'review', autoOk:'assist',
   why:'A drafting assistant could turn the committee’s list into letters, but seventy letters a year do not pay back a tool. A mail-merge template filled from the speaker spreadsheet is the right size.',
   disc:[['One spreadsheet, one source','The session dates and honoraria already sit in the speaker spreadsheet.','Value: a mail merge from it removes the wrong-date errors.'],['The personal touch','Senior speakers expect a personal note from the research director.','Keep: the director adds two lines by hand to the letters that matter.']],
   fv:'high low', reality:'Easy to do, little to gain. Seventy letters a year come to about six hours a month in the busy season.',
   metric:'Hours per invitation, and letters sent with a wrong detail', g:'sampling', hyp:'Every invitation right first time, from one template.', data:'The speaker spreadsheet, last year’s letters.'},
  {n:'Arrange travel and hotels', who:'Conference coordinators', vol:'About 50 travelling speakers a year, eight emails each', sys:'Email, travel agency portal, hotel block spreadsheet',
   notes:'Coordinators email each speaker for travel dates, home airport, hotel nights and dietary needs, then book through the Bank’s travel agency within the travel policy. Plans change, and every change is another email thread.',
   pain:'About eight emails per speaker, and last year the hotel released part of the room block before the last speakers had confirmed.',
   p:'coordinate text mid mid', alt:'input:structured', best:'fix', ok:'agent rules', auto:'review', autoOk:'',
   why:'Fix the process first: one short speaker form that asks for dates, airport, hotel nights and dietary needs once. The travel agency books from the form, and changes come through it too.',
   disc:[['The questions never change','Coordinators ask every speaker the same seven questions by email.','Fix first: put the seven questions in a form.'],['Policy limits','Speakers’ travel must stay within the Bank’s travel policy, including fare class.','Rule: the form shows the policy limits before anyone books.']],
   fv:'high mid', reality:'Quick to do with the Bank’s form tool. Medium value: fewer emails and no last-minute hotel scramble.',
   metric:'Emails per speaker, and rooms lost from the hotel block', g:'privacy logging', hyp:'Every speaker booked from one form, without an email thread.', data:'The seven standard questions, the travel policy, the agency’s booking form.'},
  {n:'Collect bios, photos and slides', who:'Conference coordinators', vol:'About 70 speakers a year, three items each', sys:'Email, shared drive, speaker spreadsheet',
   notes:'Each speaker owes a short bio, a photo for the programme and final slides two days before the session. Coordinators track what has arrived in the spreadsheet and send reminders by hand.',
   pain:'A third of slide decks arrive on the morning of the session, and the AV team loads them from USB sticks.',
   p:'coordinate structured mid low', alt:'shape:extract', best:'rules', ok:'agent fix', auto:'auto', autoOk:'review',
   why:'Deadline reminders and a single upload link per speaker, driven by the tracker. It is a workflow rule, not an AI job.',
   disc:[['The tracker is there','The spreadsheet already lists every item and its due date.','Feasibility: reminders on top of it are a small build.'],['Late slides happen','Some speakers revise their slides until the last minute, whatever the reminders say.','Keep: a person at the AV desk for late changes.']],
   fv:'high mid', reality:'Simple engineering on a tracker that already exists. Medium value: calmer mornings and fewer slides on USB sticks.',
   metric:'Items received by the deadline, and slides loaded on the day', g:'logging', hyp:'Every bio, photo and slide deck in before the deadline, without a chase by hand.', data:'The speaker tracker with due dates, an upload folder per speaker.'},
  {n:'Brief the moderators', who:'Conference coordinators and senior economists', vol:'About 20 sessions a year, three papers each', sys:'Working papers, speaker bios, Word',
   notes:'Each session has a moderator, usually a senior economist, who needs a one-page brief: who the speakers are, what each paper finds, the timings and two or three questions to open the discussion. Coordinators put the briefs together from the papers and bios.',
   pain:'Half a day per brief, and moderators say they still end up reading every paper in full.',
   p:'summarize text low mid', alt:'shape:draft', best:'summarize', ok:'draft retrieve', auto:'review', autoOk:'assist',
   why:'Summarise each paper and bio into the one-page brief, with the timings filled in. The moderator checks it and writes their own questions.',
   disc:[['Papers are long','Conference papers run to forty pages with appendices.','Value: a fair summary is where the half day goes.'],['Unpublished work','Some papers are drafts the authors have not yet released.','Data: keep them inside the Bank’s approved environment.']],
   fv:'high mid', reality:'Feasible now with an approved assistant. Medium value: ten days a year back, and better-prepared moderators.',
   metric:'Hours per moderator brief, and moderators who use it as written', g:'sampling privacy', hyp:'A one-page brief for every session a week ahead, in an hour, not half a day.', data:'The papers, speaker bios, the session timetable, a brief template.'},
  ]},

 {fn:'events', area:'ev-public',
  proc:{id:'schools', name:'School programme bookings', d:'Take bookings for classroom sessions on money and the economy, share out the places fairly and send teachers what they need.', rating:2, why:'About 160 sessions a year, booked through a form that asks too little. Most of the work is a better form and a published priority rule; tailoring the materials is where language help fits.'},
  intro:'Three education officers run about 160 classroom sessions a year on money, inflation and the Bank’s job, in the learning room and online, for students aged 14 to 18. Teachers book through a web form, and in spring requests outrun places two to one. Walk a booking from form to classroom.',
  steps:[
  {n:'Complete the booking details', who:'Education programme coordinator', vol:'About 330 requests a year', sys:'Web form, email, bookings spreadsheet',
   notes:'The form asks for a school, a contact and a preferred date, then has one free-text box. The coordinator writes back to every teacher for the year group, numbers, exam syllabus, access needs and whether they want the room or an online session.',
   pain:'Three emails per booking before it is complete, and spring requests wait a week for a first reply.',
   p:'coordinate text mid low', alt:'shape:extract', best:'fix', ok:'extract rules', auto:'auto', autoOk:'review',
   why:'Fix the form first. Ask for year group, numbers, syllabus, access needs and format as fields, and the back and forth disappears. No tool should be reading a box that should never have been free text.',
   disc:[['Five questions every time','The coordinator asks the same five questions in almost every reply.','Fix first: make them fields on the form.'],['Access needs','About one booking in ten includes a student with access needs, mentioned in passing.','Rule: a required access question, so nobody misses one.']],
   fv:'high mid', reality:'Quick and cheap: the form tool is already licensed. Medium value: a week off the spring wait.',
   metric:'Emails per booking, and days to a complete request', g:'privacy', hyp:'Every booking complete on arrival.', data:'The current form, a month of the coordinator’s replies.'},
  {n:'Share out places when demand outruns them', who:'Education officers', vol:'About 160 places for about 330 requests a year', sys:'Bookings spreadsheet, calendar',
   notes:'In spring there are two requests for every place. Officers decide who gets a session, in theory giving priority to schools that have never visited and schools in the Bank’s outreach areas. In practice, the first emails get the places.',
   pain:'A head teacher complained that the same schools get sessions every year, and nobody could show how places are decided.',
   p:'decide structured mid low', alt:'shape:allocate', best:'rules', ok:'optimize', auto:'review', autoOk:'auto',
   why:'Write the priority rule down, publish it, and score every request against it. A rule is fair, explainable and cheap; an AI ranking of schools would be none of those.',
   disc:[['The rule exists on paper','The priority criteria are in the programme’s founding note but are not applied.','Rule: apply them as written, and review them once a year.'],['Fairness is the point','A public body has to show how it shares out something scarce.','Value: a published rule answers the complaint.']],
   fv:'high mid', reality:'Simple to build in the bookings spreadsheet. Medium value: a fairness the Bank can show.',
   metric:'Share of places going to first-time and priority schools, and complaints about allocation', g:'bias logging', hyp:'Places shared out by a published rule, with first-time schools first.', data:'The bookings spreadsheet, the priority criteria, past visits by school.'},
  {n:'Send materials and confirm numbers', who:'Education officers', vol:'About 160 packs a year', sys:'Shared drive, email, bookings spreadsheet',
   notes:'Two weeks before the session, an officer sends the teacher a pre-visit pack: worksheets matched to the year group and exam syllabus, a map, the photo consent form, and a request to confirm numbers. Each officer keeps their own versions of the worksheets.',
   pain:'Adapting a pack takes about two hours, and teachers have received worksheets for the wrong syllabus.',
   p:'draft text mid low', alt:'shape:coordinate', best:'draft', ok:'retrieve rules', auto:'review', autoOk:'assist',
   why:'Draft the pack from a shared library of worksheets, matched to the year group and syllabus, for the officer to check before it goes. The numbers reminder is a simple rule.',
   disc:[['Three private libraries','Each officer keeps worksheets on their own drive, in different versions.','Prepare: gather one current library first, or the tool picks old versions.'],['Five syllabuses','Five exam syllabuses cover almost every class that books.','Feasibility: a short, fixed list to match against.']],
   fv:'mid mid', reality:'Worth doing once the worksheets are in one place. Medium value: about 300 hours a year, most of them in spring.',
   metric:'Hours per pack, and packs sent for the wrong syllabus', g:'sampling', hyp:'A matched pack in half an hour, never for the wrong syllabus.', data:'One library of current worksheets, the five syllabuses, the booking details.'},
  ]},

 {fn:'events', area:'ev-public',
  proc:{id:'visitorq', name:'Visitor centre questions', d:'Answer the public’s questions about opening hours, groups, exhibits, access and old banknotes.', rating:3, why:'Steady volume, the same questions, published answers and low stakes: a good retrieval fit. The photo questions and the front desk are smaller, and need other answers.'},
  intro:'The visitor centre and money museum welcome about 70,000 people a year. Four staff answer the same questions by email, web form and at the desk: when are you open, can we bring a group, is there step-free access, can I still exchange this old note. Walk a day of questions.',
  steps:[
  {n:'Answer written questions', who:'Visitor centre staff', vol:'About 600 emails and web messages a month', sys:'Shared mailbox, website, opening hours calendar',
   notes:'Staff answer each message by hand, copying from the website and old replies: opening hours, holiday closures, group sizes, parking, step-free routes, what is on in the museum.',
   pain:'Replies take two days in summer, and last year families were told the museum was open on two days it was closed for Bank events.',
   p:'lookup text high low', alt:'shape:route', best:'retrieve', ok:'converse draft fix', auto:'review', autoOk:'auto',
   why:'Answer from the website, the opening hours calendar and the museum guide, citing the source, with staff checking replies at first. Complaints, lost property and group bookings go to a person.',
   disc:[['Hours change','Opening hours change for holidays and Bank events about twenty times a year.','Rule: one owner keeps a single hours calendar, and answers come only from it.'],['Thirty questions','Thirty questions make up about four fifths of the messages.','Value: a short, well-tested set to start with.']],
   fv:'high mid', reality:'Quick to do: the answers are already published. Medium value: about two days a week of staff time in summer.',
   metric:'Hours to a reply, and answers that turned out wrong', g:'sampling escalation', hyp:'Same-day answers to the common questions, every one from a current source.', data:'The website, the hours calendar, the museum guide, a year of replies.'},
  {n:'Identify old notes and coins from photos', who:'Museum curator', vol:'About 30 photo questions a month', sys:'Shared mailbox, banknote reference files',
   notes:'People email photos of old banknotes and coins found in drawers and attics, asking whether they can still be exchanged and what they are worth. The curator identifies the series, explains the exchange rules and says the Bank does not value collectors’ items.',
   pain:'Each takes the curator ten minutes, and replies go out once a week.',
   p:'extract media low mid', alt:'shape:lookup', best:'vision', ok:'retrieve', auto:'review', autoOk:'assist',
   why:'A vision model could recognise the series, but thirty photos a month take the curator five hours. A web page with a picture of every series and its exchange rule answers most of them before they are sent.',
   disc:[['A page would answer it','Most senders only want to know whether the note can be exchanged.','Fix first: a picture guide to every series on the website.'],['Damaged or suspect notes','A few photos show damaged or possibly counterfeit notes.','Keep: those go to the cash team, whatever the volume.']],
   fv:'mid low', reality:'Possible, but five hours a month never pays back a vision model. Write the page.',
   metric:'Photo questions a month, and days to a reply', g:'escalation', hyp:'Most people answer their own question from the picture guide.', data:'Images of every series, the exchange rules.'},
  {n:'Count what visitors ask at the desk', who:'Front desk staff', vol:'About 250 questions a day at the desk', sys:'None: answered in person',
   notes:'Most questions are asked in person at the front desk and the museum entrance. Staff answer them and move on. Nothing is written down, so nobody knows which questions are common, which signs confuse people or what the website is missing.',
   pain:'The website and the museum guide are updated from staff impressions, not counts.',
   p:'route tacit high low', alt:'shape:summarize', best:'rules', ok:'fix classify', auto:'auto', autoOk:'review',
   why:'There is nothing for any tool to read. Start with a one-tap tally of twelve topics on the desk tablet for a month; the counts then show what to fix on the website and what the written answers should cover.',
   disc:[['Twelve topics','Staff can name the dozen topics they hear most.','Data: a tally against those twelve is enough to start.'],['A tablet already on the desk','The desk has a tablet used only for the visitor book.','Feasibility: a simple tally form, nothing to buy.']],
   fv:'high mid', reality:'Cheap to start. Medium value: it points every other fix at the right questions.',
   metric:'Questions counted by topic each week', g:'sampling', hyp:'A month of counts that shows which questions to answer better.', data:'A tally form with twelve topics.'},
  ]},

 /* ---------------- Law enforcement ---------------- */
 {fn:'police', area:'pol-access',
  proc:{id:'badges', name:'Badge and access requests', d:'Take requests for building badges, set the right access level, get the right approvals and watch for misuse.', rating:3, why:'Steady volume and real security stakes. Reading the contractor emails is a fair fit for extraction; deciding who opens which door is rules and accountable approvers, never a model.'},
  intro:'About 2,400 staff and 600 contractors carry badges that open some doors and not others: the vault, the cash floor, the data halls. Every new starter, contractor and change of role needs the right level, approved by the right person. Walk a badge from request to the door.',
  steps:[
  {n:'Receive badge requests', who:'Badge office officers', vol:'About 160 requests a month', sys:'Email, PDF forms, access control system',
   notes:'Staff requests come from managers by email with a PDF form; contractor requests come from about 60 firms in their own formats. Officers read each one and key the name, employer, sponsor, dates and areas requested into the access control system.',
   pain:'About 20 minutes per request, and a quarter come back for a missing sponsor or end date.',
   p:'extract text high mid', alt:'shape:route', best:'extract', ok:'rules fix', auto:'review', autoOk:'',
   why:'Read each request and fill the access system’s request fields, sending anything missing straight back to the sender. An officer checks every record before it goes on, and the tool sets no access.',
   disc:[['Staff are already in the HR feed','New staff and role changes already arrive in the HR system’s daily feed.','Fix first: create staff requests from the feed, and extract only the contractor emails.'],['Personal details','Requests carry names, dates of birth and employers.','Data: handle them under the staff and visitor data policy.']],
   fv:'high mid', reality:'Quick to do: the fields are few and well defined. Medium value: about 50 officer hours a month.',
   metric:'Minutes per request, and requests returned for missing details', g:'privacy threshold sampling', hyp:'Every request keyed correctly within a day, with gaps sent back at once.', data:'A year of requests, the access system’s request fields.'},
  {n:'Set the level and route for approval', who:'Badge office officers and zone owners', vol:'About 160 requests a month, 40 for restricted zones', sys:'Access control system, access matrix spreadsheet, email',
   notes:'Each role maps to a set of doors in an access matrix. Requests for restricted zones (the vault, the cash floor, the data halls) also need the zone owner’s approval and a current background check. Officers look these up and email the approvers.',
   pain:'The matrix is out of date for a third of roles, so officers copy a colleague’s access instead. Audit found 70 badges with zones the holder did not need.',
   p:'route structured high high', alt:'shape:check shape:decide', best:'rules', ok:'anomaly', auto:'review', autoOk:'assist',
   why:'Set the level from the access matrix and send each restricted-zone request to its named zone owner, by rule. A person approves every restricted zone. No model decides who opens which door.',
   disc:[['The matrix is stale','A third of roles have no current entry in the matrix.','Fix first: zone owners confirm the matrix before anything is automated.'],['Approvals stay human','A zone owner must approve each restricted-zone badge by name.','Rule: the workflow routes; the owner decides.']],
   fv:'mid high', reality:'Plain engineering once the matrix is current. High value: the audit finding closes, and nobody copies access again.',
   metric:'Badges with zones the holder does not need, and days to an approved badge', g:'logging escalation rollback', hyp:'Every badge set from the matrix, and every restricted zone approved by its owner.', data:'A current access matrix, zone owners, background check dates.'},
  {n:'Review unusual badge use', who:'Security supervisors', vol:'About 25,000 badge taps a day', sys:'Access control logs, CCTV, case notes',
   notes:'Supervisors look at access logs only after something goes wrong. Patterns that might matter, such as a badge used at 3am in a zone its holder never visits, or in two buildings minutes apart, go unnoticed.',
   pain:'Last year a lost contractor badge was used for nine days before anyone noticed.',
   p:'check structured high high', alt:'shape:predict', best:'anomaly', ok:'rules', auto:'assist', autoOk:'review',
   why:'Flag badge use unlike the holder’s own pattern or their peers’, for a supervisor to look into. The supervisor decides what happens; no badge is cancelled by a model.',
   disc:[['Two years of logs','The access system keeps two years of every tap.','Data: a baseline of normal is already captured.'],['Not a watch on staff','Staff representatives will ask what is watched and why.','Risk: agree the purpose and who sees the flags before switching it on.']],
   fv:'high high', reality:'Feasible on data the Bank already holds. High value: lost and misused badges found in hours, not days.',
   metric:'Hours from misuse to a flag, and flags that proved worth a look', g:'privacy logging escalation threshold', hyp:'A lost or misused badge spotted the same day.', data:'Two years of access logs, the access matrix, reported lost badges.'},
  ]},

 {fn:'police', area:'pol-incidents',
  proc:{id:'cctv', name:'CCTV review requests', d:'Approve requests to review camera footage, find the right cameras and minutes, blur bystanders and keep footage only as long as allowed.', rating:3, why:'Real hours spent scrubbing video, but the recorder cannot search and the privacy stakes are high. The near-term wins are a proper request form and a retention rule.'},
  intro:'The Bank’s 2,600 cameras record around the clock. After an incident, a complaint or a legal request, someone asks to see what happened, and an officer has to find it, protect the people who just walked past, and delete it on time. Walk a request.',
  steps:[
  {n:'Take and approve the request', who:'Control room supervisors', vol:'About 60 requests a month', sys:'Email, phone, incident system',
   notes:'Requests arrive by email or a call: an investigator after an incident, HR in a conduct case, an insurer, outside police. Many are one line, such as “the lobby camera on Tuesday afternoon”. The supervisor chases the purpose, the authority and the time window before approving.',
   pain:'Two days of back and forth per request, and some requests are approved without a recorded purpose.',
   p:'coordinate text mid high', alt:'shape:decide', best:'fix', ok:'rules', auto:'assist', autoOk:'',
   why:'Fix the process first: a request form that requires the incident number, the purpose, the legal basis and a narrow time window, with approval by role. Viewing footage of people is an intrusion; the reason must be written down before anyone looks.',
   disc:[['No recorded purpose','A sample of last year’s requests found one in five with no purpose recorded.','Fix first: no form, no footage.'],['HR requests are different','Footage for a conduct case needs HR and legal sign-off.','Rule: those go to legal before approval.']],
   fv:'high mid', reality:'Quick and cheap. Medium value: days saved, and a defensible record of every viewing.',
   metric:'Requests with a recorded purpose, and days to approval', g:'privacy logging escalation', hyp:'Every viewing of footage has a recorded purpose and approver.', data:'A request form, the footage access policy.'},
  {n:'Find the right cameras and minutes', who:'Control room officers', vol:'About 60 requests a month, three hours of scrubbing each', sys:'Video management system, camera list, floor plans',
   notes:'The officer works out which cameras cover the place, often from memory, then scrubs through hours of video at speed to find the moment. A missed person or a wrong camera means starting again.',
   pain:'About 180 officer hours a month, and only two senior officers know which cameras cover which doors.',
   p:'extract media mid mid', alt:'shape:lookup', best:'vision', ok:'fix', auto:'review', autoOk:'assist',
   why:'Video search for motion and objects within the approved window would cut the scrubbing to minutes. But the recorder is nine years old and cannot run it, and the camera map lives in two people’s heads. Park it until the replacement.',
   disc:[['No search in the recorder','The current video system has no analytics and no way to add them.','Feasibility: blocked until the planned replacement in 2028.'],['No faces','Searching footage for a person’s face raises legal and staff questions the Bank has not settled.','Rule: motion and object search only, never face recognition.']],
   fv:'low high', reality:'High value in officer hours, low feasibility on today’s recorder. Write the requirement into the replacement and come back.',
   metric:'Officer hours per request, and requests where the moment was not found', g:'privacy logging threshold', hyp:'The right minutes found in a quarter of the time, once the recorder can search.', data:'A map of what each camera covers, footage in a recorder that can search.'},
  {n:'Blur bystanders and release footage', who:'Control room officers and the legal team', vol:'About 8 releases a month', sys:'Video editing software, video management system',
   notes:'When footage leaves the Bank, for an insurer, a court or a person asking for footage of themselves, everyone else in the frame must be blurred. Officers blur faces frame by frame, and legal approves the release.',
   pain:'A ten-minute clip takes about a day to redact.',
   p:'check media low high', alt:'shape:extract', best:'vision', ok:'rules', auto:'assist', autoOk:'',
   why:'A vision tool finds and blurs every face; finding a face to hide it is not recognising whose it is. The officer checks every frame and legal signs off, because one missed face is a privacy breach.',
   disc:[['The law decides who','Data protection law decides who may be shown and who must be hidden.','Risk: legal approves every release.'],['A mature technique','Face blurring for redaction is a well-tested, widely sold technique.','Feasibility: buy, do not build.']],
   fv:'mid mid', reality:'Medium on both axes: a day per clip becomes an hour, but every frame still needs a person’s eye.',
   metric:'Hours per released clip, and faces missed on legal review', g:'privacy logging escalation sampling', hyp:'A clip redacted in an hour, with no face missed.', data:'Past released clips with their redactions, the release policy.'},
  {n:'Keep and delete footage on schedule', who:'Control room supervisors', vol:'About 60 new holds a month, 400 clips on hold', sys:'Video management system, holds spreadsheet',
   notes:'Footage is overwritten after 30 days unless someone places a hold for an investigation or a legal case. Holds are tracked in a spreadsheet, and nobody checks when they can be lifted.',
   pain:'Some clips have been held for six years with no open case behind them.',
   p:'coordinate structured mid mid', alt:'shape:check', best:'rules', ok:'fix', auto:'review', autoOk:'auto',
   why:'Every hold gets a reason, an owner and a review date in the system. A rule reminds the owner and deletes on schedule unless they renew it. No AI is needed to keep a retention rule.',
   disc:[['Six-year-old clips','About a third of held clips have no open case behind them.','Risk: holding footage too long breaks the retention policy.'],['Legal holds','Clips under a legal hold must never be deleted by rule.','Rule: only the legal team lifts a legal hold.']],
   fv:'high mid', reality:'Simple engineering on a spreadsheet that already exists. Medium value: the Bank keeps what it should, and no more.',
   metric:'Clips held past their review date', g:'logging rollback privacy', hyp:'No clip kept a day longer than a live reason allows.', data:'The holds spreadsheet, the retention policy, open case numbers.'},
  ]},

 {fn:'police', area:'pol-ready',
  proc:{id:'training', name:'Training and certification tracking', d:'Track firearms, first aid and other certifications for 190 officers, book requalification and record the results.', rating:2, why:'Structured dates and fixed rules, kept in three spreadsheets. This is a tracking and rules job; the only reading is the certificates from outside providers.'},
  intro:'Every officer holds certifications that expire: firearms qualification twice a year for armed posts, first aid every three years, use of force and driving every year. A lapsed certificate means an officer cannot stand on a post. Walk a certificate from course to expiry.',
  steps:[
  {n:'Track expiry dates', who:'Training sergeant', vol:'190 officers, about 1,100 certificates', sys:'Spreadsheets, roster spreadsheet',
   notes:'Each building keeps its own spreadsheet of who holds what and when it expires. The training sergeant checks them each month and emails officers and their sergeants about anything due.',
   pain:'Last year four officers were rostered to armed posts with lapsed firearms qualifications before anyone noticed.',
   p:'check structured mid high', alt:'shape:coordinate', best:'rules', ok:'anomaly', auto:'review', autoOk:'auto',
   why:'One register, with reminders at 90, 60 and 30 days and a rule that stops the roster placing anyone on a post their certificates do not cover. Dates and rules: engineering, not AI.',
   disc:[['Three spreadsheets','The three buildings record the same certificates in different columns.','Fix first: merge them into one register.'],['The roster can check','The weekly roster already applies certification rules when it is built.','Rule: feed it the register, so a lapse blocks the post.']],
   fv:'high high', reality:'Simple to build and worth it: a lapsed armed officer on post is a serious failure.',
   metric:'Officers on post with a lapsed certificate, and reminders sent on time', g:'logging rollback escalation', hyp:'No officer on a post without a current certificate.', data:'The three spreadsheets, the certification rules for each post.'},
  {n:'Book requalification sessions', who:'Training sergeant and firearms instructors', vol:'Two firearms cycles a year, about 120 armed officers each', sys:'Range calendar, roster spreadsheet, email',
   notes:'Twice a year, the sergeant fits about 120 officers into range sessions with two instructors, around shifts, leave and the range’s other users. First aid and other courses are booked with outside providers as they come due.',
   pain:'About three days of juggling each cycle, and a few officers always end up on overtime to attend.',
   p:'allocate structured low mid', alt:'shape:coordinate', best:'optimize', ok:'rules', auto:'review', autoOk:'assist',
   why:'Scheduling under constraints is an optimisation job, but two cycles a year do not pay back a tool. Reserve range sessions in the roster the way leave is reserved, and book from a simple sign-up sheet.',
   disc:[['Six days a year','The juggling takes about six days a year in total.','Value: too little to pay back a dedicated tool.'],['The roster could hold it','The roster already handles leave and training blocks.','Keep: add range sessions as a training block.']],
   fv:'high low', reality:'Possible, and not worth it. Six days a year is a sign-up sheet and a calendar.',
   metric:'Days spent scheduling each cycle, and overtime hours to attend', g:'logging', hyp:'Every armed officer requalified each cycle without overtime.', data:'The range calendar, the roster, the list of armed officers.'},
  {n:'Record results and certificates', who:'Training clerk', vol:'About 90 results and certificates a month', sys:'Paper score sheets, emailed PDFs and photos, spreadsheets',
   notes:'Firearms instructors fill in paper score sheets at the range. Outside providers send first aid and driving certificates as PDFs, scans or phone photos. The clerk keys each result and expiry date into the spreadsheet.',
   pain:'A day a week of keying, and one date in thirty is keyed wrongly.',
   p:'extract media mid mid', alt:'input:text', best:'extract', ok:'vision rules', auto:'review', autoOk:'',
   why:'Read the name, course and expiry date from each outside certificate into the register, with the clerk checking low-confidence fields. The Bank’s own range scores should be entered on a tablet at the range, not read from paper.',
   disc:[['Paper at the range','Instructors write scores by hand on a form they designed years ago.','Fix first: a tablet form at the range for the Bank’s own scores.'],['Many layouts','Twelve outside providers use twelve certificate layouts, some sent as phone photos.','Prepare: ask providers for PDFs, and collect samples of each layout.']],
   fv:'mid mid', reality:'Worth doing for outside certificates once the inputs are clean. Medium value: a day a week back, and fewer wrong dates.',
   metric:'Hours keying each week, and dates keyed wrongly', g:'privacy threshold sampling', hyp:'Every certificate in the register within a day, with the right date.', data:'Samples of each provider’s certificates, the register fields.'},
  ]},

 /* ---------------- Enterprise IT ---------------- */
 {fn:'it', area:'it-desk',
  proc:{id:'software', name:'Software requests', d:'Take requests for software, check licences and security, get approval and install.', rating:3, why:'Steady volume with a lot of avoidable tickets. Most requests should never reach a person; the security review of new software is where reading help fits, with a person deciding.'},
  intro:'Staff ask IT for software about 380 times a month, from a statistics package to a diagram tool. Some titles are approved and paid for; others are new and need a security review before anyone can install them. Walk a request from ticket to laptop.',
  steps:[
  {n:'Check the request against the approved list', who:'Service desk analysts', vol:'About 380 requests a month', sys:'Ticketing, approved software spreadsheet, licence tool',
   notes:'Each request arrives as a ticket. An analyst checks the approved software spreadsheet of about 300 titles and the licence count, asks the manager to approve, and passes it on for install.',
   pain:'Two thirds of requests are for approved titles with licences free, yet each waits three days in the queue.',
   p:'lookup structured high low', alt:'shape:route', best:'fix', ok:'rules converse', auto:'auto', autoOk:'review',
   why:'Fix the process first: publish the approved titles in a self-service catalogue, with the manager’s approval as a click and the install pushed automatically. Two thirds of these tickets should never exist.',
   disc:[['The catalogue came with the tool','The device management tool includes a self-service catalogue that was never set up.','Fix first: set it up with the 300 approved titles.'],['Paid titles','About forty approved titles cost money per user.','Rule: those still need the manager’s approval and a free licence.']],
   fv:'high high', reality:'Quick and high value: about 250 tickets a month gone, with no AI involved.',
   metric:'Software tickets a month, and days from request to install', g:'logging', hyp:'Approved software installed the same day, without a ticket.', data:'The approved software list, licence counts, the catalogue tool.'},
  {n:'Review new software for security and data risk', who:'IT security analysts', vol:'About 40 new titles a month', sys:'Vendor documents, security questionnaire, risk register',
   notes:'For software not on the list, an analyst reads the vendor’s security documents, terms and data handling, fills in the Bank’s questionnaire and recommends approve, approve with conditions or reject. A security manager decides.',
   pain:'Reviews take three weeks on average, and staff find workarounds while they wait.',
   p:'check text mid high', alt:'shape:decide', best:'extract', ok:'summarize retrieve', auto:'assist', autoOk:'',
   why:'Pull the answers to the Bank’s questionnaire from the vendor’s documents, with a page reference for each, and flag what is missing. The analyst checks every answer, and the security manager decides.',
   disc:[['Vendors write for sales','Vendor security pages promise much and commit to little.','Risk: every answer traced to a contract or certificate, not a brochure.'],['Past reviews','Four years of completed reviews sit in the risk register.','Data: good examples of what a finished review looks like.']],
   fv:'mid high', reality:'High value on a slow queue. Medium feasibility: vendor documents vary widely, so a person checks every answer.',
   metric:'Days per security review, and answers corrected by the analyst', g:'logging sampling escalation', hyp:'A review in a week, not three, with every answer traced to a source.', data:'Vendor documents, the questionnaire, past completed reviews.'},
  {n:'Read licence terms before renewals', who:'Software asset manager', vol:'About 120 contracts, 10 renewals a month', sys:'Contracts on shared drives, licence tool, procurement system',
   notes:'Each contract counts licences its own way: per named user, per device, per processor core. Before a renewal or a vendor audit, the software asset manager reads the contract to find the counting rule and compares it with what is installed.',
   pain:'Half a day per contract, and a vendor audit last year found the Bank short of licences for one product and sent an unbudgeted bill.',
   p:'extract text low mid', alt:'shape:check', best:'extract', ok:'summarize retrieve', auto:'review', autoOk:'assist',
   why:'Pull the counting rule, the renewal date, the price terms and the audit clause from each contract into the licence tool, with the clause quoted, for the manager to confirm.',
   disc:[['Contracts in three places','Contracts sit with procurement, legal and on IT’s shared drive, in different versions.','Prepare: gather one current copy of each contract first.'],['A one-off backlog','Most of the effort is reading the 120 contracts once.','Value: after that, only renewals and new contracts need reading.']],
   fv:'mid mid', reality:'Medium on both axes: a useful one-off clean-up, then a small steady flow.',
   metric:'Contracts with the counting rule recorded, and shortfalls found by vendor audits', g:'sampling logging', hyp:'Every contract’s counting rule known before the renewal, not during the audit.', data:'One current copy of each contract, the licence tool fields.'},
  ]},

 {fn:'it', area:'it-desk',
  proc:{id:'phishing', name:'Phishing report triage', d:'Sort the suspicious emails staff report, block and remove the real attacks, and warn staff.', rating:4, why:'High volume, text, measured response times and years of labelled reports. Sorting fits classification well; blocking is a playbook, and the rare warnings to staff stay simple.'},
  intro:'Staff press the report button about 1,100 times a month. Most reports are marketing or harmless; about one in twenty is a real attack, and those need blocking within the hour. Walk a reported email.',
  steps:[
  {n:'Sort the reported emails', who:'Security operations analysts', vol:'About 1,100 reports a month', sys:'Report mailbox, email security gateway, threat feeds',
   notes:'Analysts open each report, check the sender, links and attachments against threat feeds, and mark it as safe, spam or phishing. Real attacks wait in the same queue as newsletters.',
   pain:'A median of four hours to confirm a real attack, mostly spent working through harmless reports first.',
   p:'route text high mid', alt:'shape:check', best:'classify', ok:'anomaly rules', auto:'review', autoOk:'',
   why:'Classify each report as safe, spam or likely phishing from its text, links and the threat feeds, and put likely attacks at the top. Analysts confirm every attack and sample the reports marked safe.',
   disc:[['Three years labelled','Every past report carries the analyst’s final label.','Data: a ready set for training and testing.'],['Missed attacks hurt','A real attack marked safe stays in mailboxes.','Rule: nothing is closed as safe below a high confidence; the rest go to an analyst.']],
   fv:'high high', reality:'Feasible now on labelled data. High value: real attacks found in minutes, not hours.',
   metric:'Minutes from report to confirmed attack, and attacks marked safe on sampling', g:'threshold sampling logging escalation', hyp:'Real attacks confirmed within 30 minutes of the first report.', data:'Three years of labelled reports, the threat feeds.'},
  {n:'Block the sender and remove copies', who:'Security operations analysts', vol:'About 55 confirmed attacks a month', sys:'Email security gateway, mail system, web proxy',
   notes:'For each confirmed attack, an analyst blocks the sender and links, searches every mailbox for copies and removes them, and checks the web proxy for anyone who clicked. Each step is in a different console.',
   pain:'Forty minutes per attack, and copies stay in mailboxes while the analyst works through the consoles.',
   p:'coordinate structured high high', alt:'', best:'rules', ok:'agent', auto:'review', autoOk:'assist',
   why:'A playbook that runs the block, the mailbox search and removal, and the click check in one go when the analyst confirms. Once the attack is confirmed, every step is fixed and needs no judgment.',
   disc:[['The tools can talk','The gateway, the mail system and the proxy all accept automated commands.','Feasibility: an integration, not research.'],['Blocking a supplier','A wrong block can cut off a real supplier’s email.','Rule: the analyst confirms first, and every block can be undone.']],
   fv:'high high', reality:'Plain engineering with high value: attacks removed in minutes.',
   metric:'Minutes from confirmation to removal, and clicks after confirmation', g:'logging rollback', hyp:'Every copy removed within ten minutes of confirmation.', data:'Console access for the three systems, the current manual steps.'},
  {n:'Warn staff about live campaigns', who:'Security awareness lead', vol:'About 3 warnings a month', sys:'Email, intranet',
   notes:'When an attack targets many staff, the awareness lead writes a short warning with a screenshot and what to do, and the security manager signs it off. Each person who reported gets an automatic thank-you.',
   pain:'Warnings sometimes go out a day late, after the campaign has peaked.',
   p:'draft text low mid', alt:'', best:'draft', ok:'retrieve rules', auto:'review', autoOk:'assist',
   why:'A drafting assistant could write the warning from the analyst’s notes, but three short warnings a month take an hour in all. A ready template with a slot for the screenshot is the right size.',
   disc:[['A template does it','Past warnings all follow the same five-line pattern.','Keep: a template, filled in by the lead.'],['Speed is the issue','The delay is in sign-off, not in writing.','Fix first: let the security manager approve warnings from a phone.']],
   fv:'high low', reality:'Easy, but an hour a month is not worth a tool. Speed up the sign-off instead.',
   metric:'Hours from confirmed campaign to staff warning', g:'logging', hyp:'Warnings out within two hours of a confirmed campaign.', data:'Past warnings, a template.'},
  ]},

 {fn:'it', area:'it-access',
  proc:{id:'patching', name:'Patch tracking', d:'Rank vulnerability scan findings, agree maintenance windows and confirm the fixes.', rating:3, why:'Large, structured and measured, but the ranking depends on an inventory with gaps, and the slowest part is negotiating windows by email.'},
  intro:'Every week the scanner checks 2,400 laptops and about 900 servers, and finds around 6,000 open issues a month. Each one needs a priority, a slot in a maintenance window and proof it was fixed. Walk a month of findings.',
  steps:[
  {n:'Rank the findings', who:'Vulnerability analysts', vol:'About 6,000 findings a month', sys:'Vulnerability scanner, asset inventory, spreadsheets',
   notes:'Analysts export the scan results to a spreadsheet and rank them by severity score, then adjust by hand for the systems they know matter: payments, the market-data feeds, anything facing the internet.',
   pain:'Two analysts spend a week a month ranking, and most findings come out as critical, so the ranking says little.',
   p:'predict structured high mid', alt:'shape:check', best:'predict', ok:'rules anomaly', auto:'review', autoOk:'assist',
   why:'Rank by how likely each issue is to be exploited and how much the system matters, using public exploit-likelihood scores and the asset inventory. The analyst reviews the top of the list.',
   disc:[['Systems with no owner','A quarter of servers in the scan have no owner or importance recorded in the inventory.','Prepare: fill in owner and importance first, or the ranking guesses.'],['Public scores exist','Public sources publish which flaws are being exploited and how likely others are to be.','Data: free inputs, updated daily.']],
   fv:'mid high', reality:'High value: the team works on what matters first. Medium feasibility until the inventory gaps are filled.',
   metric:'Analyst days spent ranking, and exploitable issues open past their target date', g:'logging sampling', hyp:'The issues most likely to be exploited fixed first, every month.', data:'Scan results, the asset inventory with owners and importance, public exploit data.'},
  {n:'Agree maintenance windows', who:'Patch coordinators and system owners', vol:'About 150 systems a month', sys:'Email, change calendar',
   notes:'Each month the coordinators email system owners to agree a time to patch. Owners propose dates and push back around busy periods, such as the days before a rate-setting meeting, and the coordinators fit it all into the change calendar.',
   pain:'Two weeks of emails every month, and a fifth of servers miss the month’s window.',
   p:'coordinate text mid mid', alt:'shape:allocate', best:'fix', ok:'rules agent', auto:'review', autoOk:'',
   why:'Fix the process first: agree a standing window for each system once a year, with the freezes around rate-setting meetings built in. Then nobody negotiates by email every month.',
   disc:[['The same answer every month','Most owners pick the same evening every month.','Fix first: make it a standing window.'],['Freezes are known','The eight meeting dates are published a year ahead.','Rule: block the freezes in the calendar every January.']],
   fv:'high mid', reality:'Quick and cheap. Medium value: two weeks of emails a month gone.',
   metric:'Days spent agreeing windows, and servers that miss the month’s window', g:'logging', hyp:'Every system patched in its standing window, without an email thread.', data:'System owners, the change calendar, the meeting dates.'},
  {n:'Confirm the fix', who:'Vulnerability analysts', vol:'About 4,500 fixes a month', sys:'Vulnerability scanner, ticketing',
   notes:'Owners close their patch tickets when they have done the work. Analysts later compare closed tickets with the next scan, and reopen the ones still showing the issue.',
   pain:'One closed ticket in eight is still vulnerable on the next scan, and nobody notices for a month.',
   p:'check structured high mid', alt:'shape:coordinate', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Connect the scanner to the ticketing system, so a ticket closes only when the rescan is clean and reopens itself if not. A plain integration rule.',
   disc:[['Closed on say-so','Tickets close when the owner says so, not when the scan agrees.','Rule: the rescan closes the ticket.'],['Laptops off the network','Laptops away from the office miss scans for weeks.','Data: use the laptop agent’s own report as well as the scan.']],
   fv:'high mid', reality:'Plain engineering. Medium value: no false closures, and analyst time back.',
   metric:'Closed tickets still vulnerable on rescan', g:'logging rollback', hyp:'No ticket closed while the issue is still there.', data:'Scanner and ticketing access, the link between findings and tickets.'},
  ]},

 {fn:'it', area:'it-change',
  proc:{id:'cab', name:'Change approval board', d:'Check change requests, weigh their risk at a weekly board and record the decisions.', rating:3, why:'Weekly and steady, with history in the change tool. Checking requests for empty sections is a good reading job; the risk call stays with the board, and the minutes are a report, not a tool.'},
  intro:'About 90 changes a week touch the Bank’s systems. Standard changes are approved in advance; about 30 a week come to the change approval board, which meets every Tuesday to weigh the risk. Walk a change from request to minutes.',
  steps:[
  {n:'Check requests are complete', who:'Change manager', vol:'About 90 change requests a week', sys:'Change tool, email',
   notes:'The change manager reads each request before the board: what changes, what could break, how it was tested and how it would be rolled back. The required fields are free text, so “N/A” and “revert if needed” pass the tool’s checks.',
   pain:'A third of requests go back for more detail, and several a month still reach the board with empty plans.',
   p:'check text high mid', alt:'shape:extract', best:'extract', ok:'rules summarize', auto:'review', autoOk:'',
   why:'Read the test and rollback sections of each request, flag any that say nothing useful, and send them back to the requester before the board. The change manager sees every flag.',
   disc:[['Good examples exist','Two years of approved changes show what a real rollback plan looks like.','Data: examples of good and empty sections.'],['Empty plans cause outages','Two of last year’s outages followed changes with no real rollback plan.','Value: fewer failed changes, not just less reading.']],
   fv:'high mid', reality:'Feasible now on text the change tool already holds. Medium value: hours back each week, and fewer weak changes reaching the board.',
   metric:'Requests sent back, and changes reaching the board with empty plans', g:'sampling logging threshold', hyp:'No change reaches the board with an empty test or rollback plan.', data:'Two years of change requests with their outcomes.'},
  {n:'Weigh the risk at the board', who:'Change approval board', vol:'About 30 changes a week', sys:'Change tool, change calendar, incident records',
   notes:'Each Tuesday the board looks at each change: what it touches, when, how similar changes have gone and what else is happening that week. It approves, delays or rejects.',
   pain:'The board spends most of its hour on routine changes and has little time for the risky few.',
   p:'predict structured mid high', alt:'shape:decide', best:'predict', ok:'anomaly rules', auto:'assist', autoOk:'',
   why:'Score each change on how similar changes have gone before, and flag clashes in the calendar, so the board spends its time on the risky few. The board decides every change.',
   disc:[['Outcomes half recorded','Only about 60% of past changes have their outcome recorded.','Prepare: record the outcome of every change from now on.'],['Clashes are rules','Two changes to the same system in one window is a calendar check.','Rule: flag clashes by rule, not by model.']],
   fv:'mid mid', reality:'Medium on both axes, and high stakes: a failed change can stop payments. The board keeps every decision.',
   metric:'Board time spent on high-risk changes, and failed changes', g:'logging escalation', hyp:'Board time goes to the changes most likely to fail.', data:'Past changes with outcomes, the incident records, the change calendar.'},
  {n:'Write the minutes', who:'Change manager', vol:'One meeting a week', sys:'Change tool, Word, email',
   notes:'After the board, the change manager writes up the minutes: each change, the decision, any conditions and the actions. The decisions were already entered in the change tool during the meeting.',
   pain:'About two hours a week, typing out what the change tool already holds.',
   p:'draft structured low low', alt:'shape:summarize', best:'rules', ok:'draft', auto:'auto', autoOk:'review',
   why:'The decisions are already in the change tool. A saved report from it is the minutes: nothing needs writing from scratch, and two hours a week does not justify a tool.',
   disc:[['Already recorded','Every decision and condition is entered in the change tool during the meeting.','Keep: report from it.'],['Nobody reads the prose','Teams look up their own change, not the minutes.','Value: a searchable list beats a document.']],
   fv:'high low', reality:'Trivial to do, and low value: a saved report.',
   metric:'Hours a week on minutes', g:'logging', hyp:'Minutes out the same afternoon, straight from the change tool.', data:'The change tool’s decision fields.'},
  ]},

 {fn:'it', area:'it-change',
  proc:{id:'assets', name:'Asset inventory', d:'Record laptops, phones and monitors in the asset register, keep track of who has what and check it against what is on desks.', rating:2, why:'The register is wrong because hand-offs are never recorded. That is a capture problem first; once devices report in, the checking is rules.'},
  intro:'The register lists about 2,400 laptops, 2,600 phones and 4,000 monitors. Last year’s floor walk found one record in seven wrong: the wrong person, the wrong floor, or a device nobody could find. Walk a laptop from delivery to the floor walk.',
  steps:[
  {n:'Record new equipment on arrival', who:'Asset technicians', vol:'About 300 devices a month', sys:'Packing slips, asset register',
   notes:'Deliveries arrive with packing slips. Technicians key the model and serial number of each device into the register by hand, then tag it.',
   pain:'One serial number in forty is keyed wrongly, and those devices never match again.',
   p:'extract structured high low', alt:'input:media', best:'rules', ok:'vision', auto:'auto', autoOk:'review',
   why:'The supplier already holds every serial number in its own system. Ask for a delivery file with each shipment and load it into the register. Nothing needs reading at all.',
   disc:[['The supplier offers it','The main supplier sends delivery files to other customers on request.','Feasibility: ask, then load.'],['Small orders','A few small orders come from other suppliers without files.','Keep: scan the barcode for those.']],
   fv:'high mid', reality:'Simple engineering. Medium value: every new record right from the start.',
   metric:'Serial numbers keyed wrongly', g:'logging', hyp:'Every new device in the register correctly, with no keying.', data:'The supplier’s delivery file format.'},
  {n:'Record who has what', who:'Desk-side technicians, managers and staff', vol:'About 250 hand-offs a month', sys:'None for most hand-offs',
   notes:'Devices change hands all the time: a monitor swapped between desks, a laptop passed to a new starter, a phone left on a leaver’s desk. The register is updated only when IT does the swap. Everything else is in people’s heads.',
   pain:'Nobody knows who has a device until it goes missing, and then nobody knows who to ask.',
   p:'coordinate tacit high mid', alt:'shape:extract', best:'rules', ok:'fix', auto:'auto', autoOk:'review',
   why:'The facts are never written down, so no tool can read them. Make a scan of the asset tag part of every hand-off, at the service desk or in a phone app, and put it in the joiner and leaver checklists.',
   disc:[['Two moments matter','Most hand-offs happen when someone joins or leaves.','Rule: tie the scan to the joiner and leaver checklists.'],['Monitors are cheap','A monitor costs less than the time it takes to track it by name.','Keep: count monitors as stock, not as named assets.']],
   fv:'high mid', reality:'Cheap to start. Medium value: a register you can trust for the devices that hold data.',
   metric:'Hand-offs recorded, and devices with an unknown holder', g:'logging', hyp:'Every laptop and phone has a known holder.', data:'A scan step at each hand-off, the joiner and leaver checklists.'},
  {n:'Check the register against reality', who:'Asset technicians', vol:'About 9,000 records, one floor walk a year', sys:'Asset register, device management system, spreadsheets',
   notes:'Once a year, technicians walk every floor with a scanner and compare what they find with the register. The walk takes three weeks, and the results are out of date before they are entered.',
   pain:'Three weeks of technician time a year, and one record in seven still wrong.',
   p:'check structured mid mid', alt:'', best:'rules', ok:'anomaly', auto:'auto', autoOk:'review',
   why:'Laptops and phones report in to the device management system every day. Compare that with the register automatically each week and list the mismatches. Walk the floors only for what does not report in.',
   disc:[['Devices already report','Every managed laptop and phone checks in daily with its serial number and last user.','Data: the check is already possible.'],['Quiet devices','A laptop silent for 30 days is lost, stored or broken.','Rule: list them weekly for follow-up.']],
   fv:'high mid', reality:'Plain engineering on data that already exists. Medium value: three weeks a year back, and lost devices found sooner.',
   metric:'Register records that match the device data, and devices silent for 30 days', g:'logging sampling', hyp:'A register that matches reality every week, not once a year.', data:'Device management data, the asset register.'},
  ]},

 /* ---------------- Human resources ---------------- */
 {fn:'hr', area:'hr-advice',
  proc:{id:'leave', name:'Leave requests', d:'Answer balance questions, approve annual leave, and decide special and parental leave.', rating:3, why:'High volume, but most of it is a better self-service page and a few rules. The judgment is in special leave, where a person decides with the policy and past cases in front of them.'},
  intro:'About 2,400 staff make some 24,000 leave requests a year. Managers approve annual leave in the HR system; special and parental leave come to HR advisers by email. Walk the leave year.',
  steps:[
  {n:'Answer balance questions', who:'HR advisers', vol:'About 300 questions a month', sys:'HR inbox, HR system, carry-over spreadsheet',
   notes:'Staff email HR to ask how much leave they have left. The self-service page shows this year’s days, but not days carried over, days bought or time off in lieu, so advisers look these up in three places and reply.',
   pain:'About 300 emails a month for a number the Bank already holds.',
   p:'lookup structured high low', alt:'shape:route', best:'fix', ok:'converse retrieve', auto:'auto', autoOk:'review',
   why:'Fix the process first: show the full balance, including carried-over and bought days, on the self-service page. A chatbot answering the question would only cover for a page that leaves out half the answer.',
   disc:[['Three places','Carried-over days sit in a spreadsheet, and bought days in payroll.','Fix first: bring them into the HR system.'],['The question goes away','When one team saw its full balance in a trial, its questions stopped.','Value: the cheapest email is the one never sent.']],
   fv:'high mid', reality:'Quick and cheap once the data is in one place. Medium value: about 300 emails a month gone.',
   metric:'Balance questions a month', g:'logging', hyp:'Nobody needs to ask HR for their own balance.', data:'The HR system, the carry-over spreadsheet, payroll records of bought days.'},
  {n:'Approve annual leave', who:'Line managers', vol:'About 2,000 requests a month', sys:'HR system, team calendars',
   notes:'Staff request annual leave in the HR system and their manager approves it. Managers cannot see who else in the team is off, and some teams have blackout periods, such as economists in the week before a rate-setting meeting, that are not written down.',
   pain:'Clashes are found after approval, and a few teams cancel approved leave late every year.',
   p:'decide structured high low', alt:'shape:check', best:'rules', ok:'fix', auto:'review', autoOk:'auto',
   why:'Show team cover on the request and check it against written blackout periods and minimum cover, by rule. The manager still approves; the rule only puts the facts in front of them.',
   disc:[['Blackouts in heads','Teams’ blackout periods are not recorded anywhere.','Fix first: each team writes its periods into the HR system.'],['Cover is visible','The HR system can already show who in a team is off on a given day.','Feasibility: a setting and a few rules.']],
   fv:'high mid', reality:'Simple to build. Medium value: fewer clashes and late cancellations.',
   metric:'Leave cancelled after approval, and leave approved into a blackout period', g:'logging', hyp:'No leave approved into a clash or a blackout period by mistake.', data:'Team calendars, written blackout periods, minimum cover per team.'},
  {n:'Decide special and parental leave', who:'HR advisers', vol:'About 90 special and 10 parental leave cases a month', sys:'HR inbox, leave policy, case notes',
   notes:'Requests for bereavement, jury service, a family emergency or parental leave come to HR by email. The adviser checks the policy, the evidence and the dates, works out the pay, and decides or advises the manager. Similar cases have not always had the same answer.',
   pain:'Staff compare notes, and two similar bereavement requests last year got different numbers of days.',
   p:'decide text mid high', alt:'shape:lookup', best:'retrieve', ok:'summarize draft', auto:'assist', autoOk:'',
   why:'Put the policy clause and similar past decisions in front of the adviser, with the dates and pay worked out. The adviser decides; leave and pay for someone in a hard moment are not a model’s call.',
   disc:[['Past cases are unsorted','Past decisions sit in email folders, not a case log.','Prepare: log each decision with its reason, from now on.'],['People in hard moments','Many requests come from people who are grieving or in crisis.','Keep: a person replies, always.']],
   fv:'mid mid', reality:'Medium on both axes, and high stakes. Consistency is the value, and past cases need logging first.',
   metric:'Days to a decision, and similar cases decided differently', g:'privacy logging bias escalation', hyp:'Similar requests get the same answer, quickly and kindly.', data:'The leave policy, a log of past decisions with reasons.'},
  ]},

 {fn:'hr', area:'hr-hiring',
  proc:{id:'jobdesc', name:'Writing job descriptions', d:'Draft job descriptions from templates, check the wording for bias, grade the role and get it approved.', rating:2, why:'About 90 new or changed descriptions a year. Drafting from templates is a modest win; wording and grading are judgments about fairness and pay that stay with people.'},
  intro:'About 90 job descriptions a year are new, or changed enough to need regrading. Each one sets out the duties, fixes the pay grade and decides who will think the job is for them. Walk a description from first draft to approval.',
  steps:[
  {n:'Draft from the template', who:'Hiring managers and HR advisers', vol:'About 90 descriptions a year', sys:'Word templates, role profiles, past descriptions',
   notes:'Hiring managers start from an old description, often for a different role, and edit it. HR advisers then rewrite it into the Bank’s template and its 40 standard role profiles.',
   pain:'Four rounds of edits on average, and a week before a description is ready.',
   p:'draft text low mid', alt:'shape:summarize rep:mid', best:'draft', ok:'retrieve', auto:'review', autoOk:'assist',
   why:'Draft the description in the Bank’s template from the closest role profile and the manager’s notes on what is different. The adviser and the manager edit it.',
   disc:[['Forty profiles','Most roles are close to one of forty standard profiles.','Data: start from the profile, not an old description.'],['The manager knows the job','Only the manager knows what is really different about this role.','Keep: a short set of questions for the manager comes first.']],
   fv:'high mid', reality:'Feasible now. Medium value: days off every posting.',
   metric:'Rounds of edits, and days to a final draft', g:'sampling bias', hyp:'A good first draft in a day, final after two rounds of edits.', data:'The template, the 40 role profiles, a year of final descriptions.'},
  {n:'Check the wording for bias', who:'HR advisers', vol:'About 90 descriptions a year', sys:'Word, inclusive language guide',
   notes:'Advisers read each draft for wording that might put people off applying: gendered words, jargon, and requirements the job does not need, such as a degree for a role that has never needed one. The guide is twenty pages long and applied unevenly.',
   pain:'Applicant pools for some roles are far narrower than the people who could do them, and wording is one known cause.',
   p:'suggest text low mid', alt:'shape:check', best:'recommend', ok:'rules retrieve', auto:'assist', autoOk:'',
   why:'Flag wording against the Bank’s guide and suggest plainer alternatives, with the reason for each. The adviser accepts or rejects every suggestion, and the suggestions themselves are checked for bias.',
   disc:[['A word list is a start','A list of gendered and excluding words catches the obvious cases.','Rule: run the word list first; suggestions cover what it misses.'],['Requirements matter most','Unneeded requirements narrow the pool more than any single word.','Value: question every requirement, not only the adjectives.']],
   fv:'high mid', reality:'Feasible now, with a person deciding. Medium value: wider applicant pools for the roles that need them.',
   metric:'Suggestions accepted, and applicant pools by group for revised roles', g:'bias sampling logging', hyp:'Every description free of wording that narrows who applies.', data:'The inclusive language guide, past descriptions, applicant pools by role.'},
  {n:'Grade the role', who:'Grading panel', vol:'About 90 roles a year', sys:'Grading scheme, grading spreadsheet, past gradings',
   notes:'A panel of three scores each role against the grading scheme’s factors: knowledge, complexity, impact and people managed. The score sets the pay grade. Managers sometimes write descriptions to reach a grade.',
   pain:'A two-week wait for a panel, and appeals when similar roles land in different grades.',
   p:'decide text low high', alt:'shape:check', best:'retrieve', ok:'summarize recommend', auto:'assist', autoOk:'',
   why:'Show the panel similar roles already graded, with their scores and reasons, so like is compared with like. The panel scores and decides; pay grades are not a model’s call.',
   disc:[['Equal pay','Grading decides pay, and inconsistent grading is an equal pay risk.','Risk: the panel owns every grade, and outcomes are reviewed by group.'],['Past gradings are scored','Five years of gradings sit in a spreadsheet with their factor scores.','Data: ready for finding similar roles.']],
   fv:'mid mid', reality:'Medium on both axes, and high stakes. Consistency is the prize.',
   metric:'Grading appeals upheld, and similar roles in different grades', g:'bias logging escalation', hyp:'Similar roles graded the same, with fewer appeals.', data:'The grading scheme, five years of graded roles with scores.'},
  {n:'Approve and post', who:'HR business partners and department heads', vol:'About 90 approvals a year', sys:'Email, applicant tracking system',
   notes:'The final description needs the department head’s and the HR business partner’s approval before it goes into the applicant tracking system. Approvals are chased by email.',
   pain:'Descriptions wait a week for approval, mostly sitting in inboxes.',
   p:'coordinate structured low mid', alt:'', best:'rules', ok:'agent', auto:'auto', autoOk:'review',
   why:'An approval step in the applicant tracking system, with a reminder after two days. A workflow rule; no AI needed.',
   disc:[['The route exists','The applicant tracking system already routes job offers for approval.','Feasibility: reuse the same route for descriptions.'],['Two approvers','Only two people ever need to approve.','Keep: a simple, fixed route.']],
   fv:'high mid', reality:'Simple configuration. Medium value: a week off every hire.',
   metric:'Days waiting for approval', g:'logging', hyp:'Every description approved within two days.', data:'The applicant tracking system’s approval route.'},
  ]},

 {fn:'hr', area:'hr-hiring',
  proc:{id:'onboarding', name:'Onboarding new starters', d:'Collect a new starter’s details, line up IT, desk, badge and pay, and plan their first weeks.', rating:3, why:'About 25 starters a month, five teams to line up and a measured failure: one starter in five arrives to something missing. The fix is a portal and a workflow; drafting the first-weeks plan is the language job.'},
  intro:'About 300 people a year start at the Bank, staff and interns together. Before day one, IT, facilities, security, payroll and the manager all have something to do, and nobody sees the whole list. Walk a new starter to their first morning.',
  steps:[
  {n:'Collect the starter’s details', who:'HR officers', vol:'About 25 starters a month, 8 forms each', sys:'Email, PDF forms, HR system',
   notes:'After the offer is accepted, HR emails the starter eight forms: personal details, bank details, tax, emergency contacts, right to work and more. They come back as scans and phone photos, and officers key them into the HR system.',
   pain:'Two hours of keying per starter, and forms still missing on day one for one starter in four.',
   p:'coordinate text high mid', alt:'shape:extract input:media', best:'fix', ok:'extract rules', auto:'review', autoOk:'',
   why:'Fix the process first: a starter portal where the person enters their own details once, straight into the HR system. Reading scanned forms with a tool would automate a step that should not exist.',
   disc:[['The same details, eight times','Half the fields on the eight forms ask for details already given on another.','Fix first: ask each detail once, in one portal.'],['Right to work','Right-to-work documents must be seen and checked by a person under the law.','Keep: an officer checks identity documents in person or by approved video call.']],
   fv:'high high', reality:'Quick and high value: about 50 hours a month of keying gone, and complete records before day one.',
   metric:'Hours keying per starter, and starters with forms missing on day one', g:'privacy logging', hyp:'Every starter’s details complete a week before day one, keyed by nobody.', data:'The HR system’s starter portal, the eight forms.'},
  {n:'Line up IT, desk, badge and pay', who:'HR officers', vol:'About 25 starters a month, five teams each', sys:'Email, IT ticketing, facilities requests, badge office, payroll',
   notes:'For each starter an officer emails IT for a laptop and accounts, facilities for a desk, the badge office for access and payroll for set-up, then tells the manager. Each team has its own form, and the officer tracks replies in a spreadsheet.',
   pain:'One starter in five arrives to a missing laptop, badge or desk, and officers spend the week before chasing.',
   p:'coordinate structured high mid', alt:'input:text', best:'rules', ok:'agent fix', auto:'auto', autoOk:'review',
   why:'When the hire is confirmed in the HR system, a workflow raises the four requests with the start date and role, tracks them and warns the officer of anything not done three days out. Fixed steps, so rules, not AI.',
   disc:[['The feed already exists','IT and the badge office already receive a daily feed of joiners from the HR system.','Feasibility: extend the feed to facilities and payroll.'],['Start dates move','About a third of start dates change after the offer.','Rule: a changed date updates all four requests at once.']],
   fv:'high high', reality:'Plain engineering with a clear prize: every starter ready on day one.',
   metric:'Starters missing something on day one, and officer hours spent chasing', g:'logging rollback', hyp:'Every starter has a laptop, badge, desk and pay set up on day one.', data:'The HR joiner feed, each team’s request form.'},
  {n:'Plan the first weeks with the manager', who:'Hiring managers', vol:'About 25 plans a month', sys:'Word, intranet, learning system',
   notes:'Managers are asked to write a plan for the first four weeks: who to meet, what to read, which courses are mandatory. Many reuse an old plan; some write nothing, and the starter spends the first week reading the intranet.',
   pain:'In the starter survey, a third say their first week had no plan.',
   p:'draft text mid low', alt:'shape:suggest', best:'draft', ok:'retrieve', auto:'review', autoOk:'assist',
   why:'Draft a first-weeks plan from the role, the team’s contacts and the mandatory courses, for the manager to edit and own. It turns a blank page into a ten-minute job.',
   disc:[['Mandatory courses are listed','Mandatory training by role is already in the learning system.','Data: a reliable input.'],['The manager’s plan','A plan the manager has not read helps nobody.','Keep: the manager edits and sends it.']],
   fv:'high mid', reality:'Feasible now. Medium value: a better first month for 300 people a year.',
   metric:'Starters reporting a plan in their first week', g:'sampling', hyp:'Every starter has a plan on day one.', data:'Role profiles, team contact lists, mandatory courses by role.'},
  ]},

 {fn:'hr', area:'hr-perf',
  proc:{id:'learning', name:'Training catalogue', d:'Keep the course catalogue current, answer questions about courses and suggest courses that fit someone’s goals.', rating:3, why:'A steady stream of the same questions over a catalogue that is a third out of date. Retrieval helps once there is one current catalogue; suggestions stay with the person and their manager.'},
  intro:'The learning team of six looks after about 600 courses: in-house, e-learning and from outside providers. Staff ask about them about 250 times a month, and managers want courses that fit the goals set in reviews. Walk the catalogue.',
  steps:[
  {n:'Keep course descriptions current', who:'Learning advisers', vol:'About 600 courses, 40 changes a month', sys:'Learning system, provider websites, PDFs',
   notes:'Outside providers change their courses, dates and prices through the year. Advisers rewrite each provider’s description into the catalogue’s format: what it covers, who it is for, length, cost and how to book.',
   pain:'A third of entries are out of date, and staff have booked courses that no longer exist.',
   p:'extract text mid low', alt:'shape:draft', best:'extract', ok:'draft rules', auto:'review', autoOk:'',
   why:'Pull the fields from each provider’s description into the catalogue format and flag what has changed since last time, for an adviser to approve.',
   disc:[['Forty providers','Forty providers account for nearly all outside courses.','Feasibility: a known, limited set of sources.'],['Dead courses','About 80 courses have not run in two years.','Fix first: retire them before tidying the rest.']],
   fv:'high mid', reality:'Feasible now. Medium value: a catalogue people can trust.',
   metric:'Entries out of date, and bookings for courses that no longer run', g:'sampling threshold', hyp:'Every entry current within a month of a provider’s change.', data:'Provider descriptions, the catalogue format.'},
  {n:'Answer questions about courses', who:'Learning advisers', vol:'About 250 questions a month', sys:'Learning inbox, learning system, intranet',
   notes:'Staff ask whether a course exists, who pays, whether it counts towards a professional qualification and how to book. Advisers answer from the catalogue, the training policy and memory.',
   pain:'Replies take three days, and answers about funding differ between advisers.',
   p:'lookup text high low', alt:'shape:route', best:'retrieve', ok:'converse fix', auto:'review', autoOk:'auto',
   why:'Answer from the catalogue and the training policy, citing both, and send funding questions to an adviser. It only works once there is one catalogue to answer from.',
   disc:[['Two catalogues','The learning system and an old intranet page list different courses.','Prepare: retire the intranet page and keep one catalogue.'],['Funding is a decision','Who pays for an outside course is the manager’s decision under the policy.','Rule: the assistant explains the policy; it never approves funding.']],
   fv:'mid mid', reality:'Medium on both axes: steady questions, but the source needs tidying first.',
   metric:'Days to an answer, and answers that cite the wrong course', g:'sampling escalation', hyp:'Most course questions answered the same day, from one catalogue.', data:'One current catalogue, the training policy, a year of questions.'},
  {n:'Suggest courses that fit someone’s goals', who:'Learning advisers and managers', vol:'About 80 requests a month', sys:'Learning system, review goals, email',
   notes:'After reviews, staff and managers ask what training would help with a goal, such as “present to the board” or “learn to code for data work”. Advisers suggest three or four courses from what they know.',
   pain:'Suggestions depend on which adviser answers, and newer advisers know a fraction of the catalogue.',
   p:'suggest text mid mid', alt:'shape:lookup', best:'recommend', ok:'retrieve', auto:'assist', autoOk:'review',
   why:'Suggest a short list from the catalogue with a reason for each, for the person and their manager to choose from. Development choices shape careers, so people choose.',
   disc:[['Goals are personal','Review goals are personal data, linked to pay and careers.','Data: use only what the person shares in their request.'],['Same goal, same suggestions','Suggestions must not differ by group for the same goal.','Risk: sample suggestions for bias.']],
   fv:'mid mid', reality:'Medium on both axes once the catalogue is current. A sensible second step.',
   metric:'Suggestions taken up, and how people rate the course afterwards', g:'bias privacy sampling', hyp:'Everyone gets good suggestions, whoever answers.', data:'A current catalogue, past bookings by goal.'},
  ]},

 {fn:'hr', area:'hr-perf',
  proc:{id:'exitint', name:'Exit interview themes', d:'Hold exit interviews, record why people leave, and report the themes to leadership without identifying anyone.', rating:1, why:'Fifteen interviews a month, personal and candid. The gap is that reasons are never recorded the same way; after that, a general assistant and a privacy rule are all it needs.'},
  intro:'About 25 people leave the Bank each month, and about 15 agree to an exit interview with an HR business partner. Every quarter leadership asks why people leave. Walk the interviews to the quarterly report.',
  steps:[
  {n:'Hold the interview and record the reasons', who:'HR business partners', vol:'About 15 interviews a month', sys:'Meeting rooms, Word notes, HR system',
   notes:'Each partner runs the interview their own way and keeps notes in their own format. The HR system has a reason-for-leaving field, but seven leavers in ten are recorded as “resigned, other”. The real reasons, such as a manager, pay or no route to promotion, stay in the partner’s memory.',
   pain:'Leadership asks why people leave, and HR can only answer with anecdotes.',
   p:'route tacit low mid', alt:'shape:summarize', best:'rules', ok:'fix', auto:'review', autoOk:'',
   why:'The reasons are not written down in any usable form, so no tool can read them. Agree a short list of reasons and the same six questions, and record each leaver’s reasons against the list at the end of the interview.',
   disc:[['“Resigned, other”','Seven leavers in ten carry the same empty reason.','Data: a fixed list of about a dozen reasons makes them countable.'],['Candour','Leavers speak more freely when nothing is recorded word for word.','Keep: record the reasons, not a transcript.']],
   fv:'high mid', reality:'Cheap to start. Medium value: the first real answer to why people leave.',
   metric:'Leavers with a specific reason recorded', g:'privacy', hyp:'Every leaver’s reasons counted the same way.', data:'A list of reasons, six standard questions.'},
  {n:'Summarise the interviews into themes', who:'HR business partners', vol:'About 45 interviews a quarter', sys:'Word notes, spreadsheet',
   notes:'Each quarter one partner reads all the notes, groups what was said into themes and counts how often each comes up.',
   pain:'Two days a quarter, and the themes are named differently each time.',
   p:'summarize text low mid', alt:'shape:route', best:'summarize', ok:'classify', auto:'review', autoOk:'assist',
   why:'Summarising 45 sets of notes is a fair task for a summary tool, but two days a quarter does not justify a dedicated one. The approved general assistant, with names removed first, is the right size.',
   disc:[['Two days a quarter','The work is about two days, four times a year.','Value: too small for a dedicated tool.'],['Names in the notes','Notes name managers and colleagues.','Data: remove names before anything goes into a tool.']],
   fv:'high low', reality:'Easy and small. Use the general assistant and keep the time.',
   metric:'Days to the quarterly themes', g:'privacy sampling', hyp:'Themes ready in half a day, counted the same way each quarter.', data:'Interview notes with names removed, the list of reasons.'},
  {n:'Report to leadership without identifying anyone', who:'Head of HR', vol:'Four reports a year', sys:'Word, slides',
   notes:'The themes go to the executive committee with comments from leavers. In a small team, a theme and a quote can point straight at one person, and the manager they left may be in the room.',
   pain:'Last year a quote in the report was traced to a leaver by their former team.',
   p:'check text low high', alt:'shape:draft', best:'rules', ok:'extract', auto:'review', autoOk:'assist',
   why:'A minimum group rule: no theme reported for fewer than five leavers, and no quote that names a team, grade or place. Applied before the head of HR writes the report, a rule protects people better than any tool.',
   disc:[['Small numbers','Most teams lose one or two people a year.','Rule: report by division, never by team.'],['Trust','One identified leaver makes the next ones say nothing.','Value: candid interviews depend on it.']],
   fv:'high mid', reality:'Easy, and worth it: the whole exercise depends on leavers trusting it.',
   metric:'Themes and quotes reported below the minimum group size', g:'privacy escalation', hyp:'No leaver can be identified from the report.', data:'The reporting rule, leaver numbers by division.'},
  ]},
];
